import functools
import sqlite3

def retry_on_deadlock(max_retries: int = 3):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(conn, *args, **kwargs):
            for attempt in range(max_retries + 1):
                try:
                    return fn(conn, *args, **kwargs)
                except sqlite3.OperationalError as exc:
                    conn.rollback()
                    msg = str(exc).lower()
                    is_transient = ('locked' in msg) or ('deadlock' in msg)
                    if not is_transient or attempt == max_retries:
                        raise
                except Exception:
                    conn.rollback()
                    raise
        return wrapper
    return decorator

