import bisect
import hashlib

class ConsistentHashRouter:
    def __init__(self, shards: list[str], vnodes: int = 100):
        self.vnodes = vnodes
        self._ring: list[int] = []
        self._nodes: dict[int, str] = {}
        self._shards: set[str] = set()
        for shard in shards:
            self.add_shard(shard)

    @staticmethod
    def _hash(value: str) -> int:
        return int(hashlib.md5(value.encode('utf-8')).hexdigest(), 16)

    def add_shard(self, shard: str) -> None:
        if shard in self._shards:
            return
        self._shards.add(shard)
        for i in range(self.vnodes):
            pos = self._hash(f'{shard}#{i}')
            while pos in self._nodes:
                pos = (pos + 1)
            self._nodes[pos] = shard
            bisect.insort(self._ring, pos)

    def remove_shard(self, shard: str) -> None:
        if shard not in self._shards:
            return
        self._shards.remove(shard)
        self._nodes = {pos: s for pos, s in self._nodes.items() if s != shard}
        self._ring = sorted(self._nodes.keys())

    def get_shard(self, key: str) -> str:
        if not self._ring:
            raise ValueError('Нет доступных шардов')
        pos = self._hash(key)
        idx = bisect.bisect_left(self._ring, pos)
        if idx == len(self._ring):
            idx = 0
        return self._nodes[self._ring[idx]]

